# -*- coding: utf-8 -*-
"""
Savora Kitchen Intelligence — Offline GPU Food Waste & Prep Forecaster
Runs natively on Windows with NVIDIA CUDA GPU acceleration (XGBoost hist + CUDA)
Includes automatic Dual-UI support (CustomTkinter + Native Dark Tkinter Fallback)
"""
import os
import sys
import io
import base64
import warnings
import tkinter as tk
from tkinter import ttk, messagebox

warnings.filterwarnings("ignore")

EMBEDDED_DATASET_B64 = ""

def ensure_dataset_file():
    """Locate Food_Waste_Prediction_Dataset.xlsx on disk or extract from embedded payload."""
    candidates = [
        os.path.join(os.path.dirname(os.path.abspath(sys.argv[0])), "Food_Waste_Prediction_Dataset.xlsx"),
        os.path.join(os.getcwd(), "Food_Waste_Prediction_Dataset.xlsx"),
    ]
    if hasattr(sys, "_MEIPASS"):
        candidates.insert(0, os.path.join(sys._MEIPASS, "Food_Waste_Prediction_Dataset.xlsx"))
    for path in candidates:
        if os.path.exists(path):
            return path
    # Fallback: write embedded dataset to current directory or temp
    target_path = candidates[0]
    try:
        with open(target_path, "wb") as f:
            f.write(base64.b64decode(EMBEDDED_DATASET_B64))
        return target_path
    except Exception:
        return io.BytesIO(base64.b64decode(EMBEDDED_DATASET_B64))


def detect_compute_device():
    """Detect NVIDIA GPU via PyTorch or XGBoost CUDA probe."""
    try:
        import torch
        if torch.cuda.is_available():
            return "cuda", f"GPU Active: {torch.cuda.get_device_name(0)}"
    except Exception:
        pass
    try:
        import numpy as np
        from xgboost import XGBRegressor
        probe = XGBRegressor(n_estimators=1, tree_method="hist", device="cuda")
        probe.fit(np.array([[1.0, 2.0], [3.0, 4.0]]), np.array([1.0, 2.0]))
        return "cuda", "GPU Active: NVIDIA CUDA (XGBoost Hist)"
    except Exception:
        return "cpu", "CPU Mode (CUDA Fallback)"


class SavoraEngine:
    def __init__(self):
        import pandas as pd
        import numpy as np
        from sklearn.preprocessing import OrdinalEncoder
        from sklearn.model_selection import train_test_split
        from sklearn.metrics import mean_absolute_error, r2_score

        self.pd = pd
        self.np = np
        self.categorical_features = [
            "Restaurant_Name", "City", "Cuisine", "Food_Item",
            "Weather", "Weekend", "Holiday"
        ]
        self.numerical_features = ["Temperature_C", "Discount_Percent", "Customers"]

        self.device_type, self.device_label = detect_compute_device()

        dataset_source = ensure_dataset_file()
        self.df_history = pd.read_excel(dataset_source)

        self.cuisine_to_dishes = (
            self.df_history.groupby("Cuisine")["Food_Item"]
            .unique()
            .apply(list)
            .to_dict()
        )
        self.all_dishes = sorted(self.df_history["Food_Item"].unique().tolist())

        self.encoder = OrdinalEncoder(handle_unknown="use_encoded_value", unknown_value=-1)
        df_encoded = self.df_history.copy()
        df_encoded[self.categorical_features] = self.encoder.fit_transform(
            self.df_history[self.categorical_features].astype(str)
        )

        X = df_encoded[self.categorical_features + self.numerical_features]
        y_prepared = df_encoded["Prepared_Quantity"]
        y_waste = df_encoded["Waste_Amount_kg"]

        X_train, X_test, y_prep_train, y_prep_test, y_waste_train, y_waste_test = train_test_split(
            X, y_prepared, y_waste, test_size=0.2, random_state=42
        )

        try:
            from xgboost import XGBRegressor
            xgb_params = dict(
                n_estimators=100,
                max_depth=4,
                learning_rate=0.1,
                tree_method="hist",
                device=self.device_type,
                random_state=42
            )
            eval_prep = XGBRegressor(**xgb_params)
            eval_waste = XGBRegressor(**xgb_params)
            eval_prep.fit(X_train, y_prep_train)
            eval_waste.fit(X_train, y_waste_train)

            self.prepared_model = XGBRegressor(**xgb_params)
            self.waste_model = XGBRegressor(**xgb_params)
            self.prepared_model.fit(X, y_prepared)
            self.waste_model.fit(X, y_waste)
        except ImportError:
            from sklearn.ensemble import HistGradientBoostingRegressor
            self.device_label = "Sklearn HistGBT (Install xgboost for CUDA)"
            eval_prep = HistGradientBoostingRegressor(max_iter=100, max_depth=4, learning_rate=0.1, random_state=42)
            eval_waste = HistGradientBoostingRegressor(max_iter=100, max_depth=4, learning_rate=0.1, random_state=42)
            eval_prep.fit(X_train, y_prep_train)
            eval_waste.fit(X_train, y_waste_train)

            self.prepared_model = HistGradientBoostingRegressor(max_iter=100, max_depth=4, learning_rate=0.1, random_state=42)
            self.waste_model = HistGradientBoostingRegressor(max_iter=100, max_depth=4, learning_rate=0.1, random_state=42)
            self.prepared_model.fit(X, y_prepared)
            self.waste_model.fit(X, y_waste)

        prep_preds = eval_prep.predict(X_test)
        waste_preds = eval_waste.predict(X_test)
        self.prep_mae = mean_absolute_error(y_prep_test, prep_preds)
        self.prep_r2 = r2_score(y_prep_test, prep_preds)
        self.waste_mae = mean_absolute_error(y_waste_test, waste_preds)
        self.waste_r2 = r2_score(y_waste_test, waste_preds)

    def predict(self, input_dict):
        input_df = self.pd.DataFrame([input_dict])
        input_df[self.categorical_features] = self.encoder.transform(
            input_df[self.categorical_features].astype(str)
        )
        features_ordered = input_df[self.categorical_features + self.numerical_features]
        pred_prepared = max(0.0, float(self.prepared_model.predict(features_ordered)[0]))
        pred_waste = max(0.0, float(self.waste_model.predict(features_ordered)[0]))
        return pred_prepared, pred_waste


